// ===== КАТЕГОРИИ =====
document.querySelectorAll(".category-btn").forEach(btn => {
  btn.onclick = () => {
    document.querySelectorAll(".category-btn").forEach(b => b.classList.remove("active"));
    btn.classList.add("active");
    state.category = btn.dataset.category;
    state.currentTaskId = null;
    state.levelProgress = 0;
    state.completedTasks = 0;
    state.errors = 0;
    updateProgress();
    showTaskSelection();
  };
});

// ===== СЛОЖНОСТЬ =====
document.querySelectorAll(".difficulty-btn").forEach(btn => {
  btn.onclick = () => {
    document.querySelectorAll(".difficulty-btn").forEach(b => b.classList.remove("active"));
    btn.classList.add("active");
    state.level = Number(btn.dataset.level);
    state.levelProgress = 0;
    state.completedTasks = 0;
    state.errors = 0;
    updateProgress();
    if (state.currentTaskId && TASKS[state.category][state.currentTaskId]) {
      renderSpecificTask(state.currentTaskId);
    } else {
      showTaskSelection();
    }
  };
});

// ===== СТАТИСТИКА =====
const modal = document.getElementById("statsModal");
const statsBtn = document.getElementById("statsBtn");
const closeBtn = document.querySelector(".modal-close");

statsBtn.onclick = () => {
  document.getElementById("statScore").textContent = state.score;
  document.getElementById("statCorrect").textContent = state.metrics.totalCorrect;
  document.getElementById("statErrors").textContent = state.metrics.totalErrors;
  document.getElementById("statTime").textContent = state.metrics.totalTime;
  
  const total = state.metrics.totalCorrect + state.metrics.totalErrors;
  const accuracy = total > 0 ? Math.round((state.metrics.totalCorrect / total) * 100) : 0;
  document.getElementById("accuracyValue").textContent = `${accuracy}%`;
  document.getElementById("accuracyFill").style.width = `${accuracy}%`;
  
  modal.style.display = "block";
};

closeBtn.onclick = () => { modal.style.display = "none"; };
window.onclick = (e) => { if (e.target === modal) modal.style.display = "none"; };

document.getElementById("resetAllStats").onclick = () => {
  state.score = 0;
  state.metrics = { totalTime: 0, totalErrors: 0, totalCorrect: 0, sessions: [] };
  saveProgress();
  showToast("Статистика сброшена!", "success");
  modal.style.display = "none";
};

// ===== ЗАПУСК =====
loadProgress();
showTaskSelection();
updateProgress();